(function(root){
const cleanWord=s=>String(s??'').toUpperCase().replace(/[\s'’-]/g,'');
const validWord=s=>typeof s==='string'&&/^[A-Z]{1,24}$/.test(s);
const validNumber=s=>typeof s==='string'&&/^(0|[1-9]\d{0,3})$/.test(s)&&Number(s)<=1000;
function validCustom(q){return!!q&&typeof q.prompt==='string'&&q.prompt.trim().length>0&&q.prompt.length<=120&&[1,2,3].includes(Number(q.level))&&(q.mode==='numbers'?validNumber(q.answer)&&(!q.acceptedAnswers||Array.isArray(q.acceptedAnswers)&&!q.acceptedAnswers.length):['vocabulary','spelling'].includes(q.mode)&&validWord(q.answer)&&(!q.acceptedAnswers||Array.isArray(q.acceptedAnswers)&&q.acceptedAnswers.length<=12&&q.acceptedAnswers.every(validWord)));}
function normalizeQuestion(row){if(typeof row==='number'||typeof row==='string')row=/^\d+$/.test(String(row))?{mode:'numbers',answer:String(row)}:{mode:'spelling',answer:String(row)};if(!row||typeof row!=='object'||Array.isArray(row))return null;const mode=({words:'vocabulary',word:'vocabulary',name:'spelling',names:'spelling',number:'numbers'})[row.mode]||row.mode;if(row.acceptedAnswers!==undefined&&!Array.isArray(row.acceptedAnswers))return null;const answer=mode==='numbers'?String(row.answer??'').trim():cleanWord(row.answer);const acceptedAnswers=Array.isArray(row.acceptedAnswers)?[...new Set(row.acceptedAnswers.map(cleanWord))]:[];const prompt=mode==='numbers'&&validNumber(answer)?root.numberToWords(Number(answer)):String(row.prompt??(mode==='spelling'?answer:'')).trim();const q={mode,answer,prompt,acceptedAnswers,level:mode==='numbers'?(Number(answer)<=20?1:Number(answer)<=100?2:3):Number(row.level||1),topic:typeof row.topic==='string'?row.topic.slice(0,80):'Personal practice'};return validCustom(q)?q:null;}
function parseJSONList(text){let rows;try{const raw=String(text).trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');const parsed=JSON.parse(raw);rows=Array.isArray(parsed)?parsed:parsed?.questions;if(!Array.isArray(rows))throw Error('Use a JSON array of questions.');if(rows.length>3000)throw Error('Use no more than 3,000 questions.');}catch(err){return{questions:[],errors:[err.message.startsWith('Use ')?err.message:'The JSON could not be read. Paste only the JSON list, then check commas and quotation marks.']};}const questions=[],errors=[],seen=new Set();for(let i=0;i<rows.length;i++){const q=normalizeQuestion(rows[i]);if(!q){errors.push(`Item ${i+1}: use vocabulary, spelling or numbers, with a valid answer and clue.`);continue}const key=[q.mode,q.prompt,q.answer].join('|');if(!seen.has(key)){seen.add(key);questions.push({...q,id:`import-${Date.now()}-${i}`})}}return{questions,errors};}
function parseWordList(text,level=1){const questions=[],errors=[],seen=new Set();const lines=String(text).split(/\r?\n/);if(lines.length>500)return{questions,errors:['Please paste no more than 500 lines.']};lines.forEach((line,i)=>{if(!line.trim())return;const [raw,clue='',aliases='']=line.split(/\t|\|/).map(x=>x.trim()),answer=cleanWord(raw),acceptedAnswers=[...new Set(aliases.split(/[,;]/).filter(Boolean).map(cleanWord))];const q={id:`paste-${Date.now()}-${i}`,answer,prompt:clue||answer,mode:clue?'vocabulary':'spelling',level:Number(level),acceptedAnswers,topic:'Personal word list'};if(!validCustom(q)){errors.push(`Line ${i+1}: use an English word (up to 24 letters), a clue up to 120 characters, and valid alternatives.`);return}const key=answer+'|'+q.prompt;if(!seen.has(key)){seen.add(key);questions.push(q)}});return{questions,errors};}
function parsePracticeList(text,level=1){return /^\s*(?:\[|\{|```)/.test(text)?parseJSONList(text):parseWordList(text,level);}
function skillForList(questions){const modes=new Set(questions.map(q=>q.mode));if(modes.size===1&&modes.has('numbers'))return'numbers';if(modes.size===1&&modes.has('spelling'))return'spelling';return modes.has('numbers')?'mixed':'words';}
function chatbotPrompt(kind='vocabulary'){
const shared='Create a practice list for Inkfang, an English-learning game.\nTopic: [REPLACE WITH YOUR TOPIC]\nLearner level: [REPLACE WITH AGE / ENGLISH LEVEL]\nNumber of items: [REPLACE WITH A NUMBER BETWEEN 2 AND 500]\n\nReturn ONLY one valid JSON array. No introduction, explanations, Markdown, comments, or trailing commas. Use double quotes. Each item must use the schema below. Give every item a different answer.\n';
const levels='Use level 1 for beginner, 2 for elementary, or 3 for challenge. Answers and acceptedAnswers must be English letters only, uppercase, 1–24 letters each. Remove spaces, hyphens and apostrophes from answers (NEW YORK becomes NEWYORK). Keep normal readable text in prompt.\n';
if(kind==='numbers')return shared+'\nCreate single whole-number targets from 0 through 1000, limited to my requested range/topic. No PINs, phone numbers, decimals, negatives, leading zeroes or strings of several answers. Use mode "numbers". answer must be a decimal digit STRING. prompt must be that same number written in English words (the game also regenerates this for accuracy). Use level 1 for 0–20, 2 for 21–100, and 3 for 101–1000. Do not use acceptedAnswers for numbers.\n\nExample structure:\n[{"mode":"numbers","level":2,"prompt":"ninety-eight","answer":"98"},{"mode":"numbers","level":3,"prompt":"one hundred and six","answer":"106"}]\n\nGenerate the requested list now.';
if(kind==='spelling')return shared+'\nCreate personal names and/or place names for spelling practice. Use mode "spelling". prompt should show the name/place in readable English. answer is its uppercase spelling with spaces, hyphens and apostrophes removed. Use an empty acceptedAnswers array unless an equally valid spelling is intentional.\n'+levels+'\nExample structure:\n[{"mode":"spelling","level":1,"prompt":"Paris","answer":"PARIS","acceptedAnswers":[]},{"mode":"spelling","level":2,"prompt":"New York","answer":"NEWYORK","acceptedAnswers":[]}]\n\nGenerate the requested list now.';
return shared+'\nCreate vocabulary questions with short, accurate English clues. Use mode "vocabulary". Each prompt must be 1–120 characters, appropriate to the learner level, and must not reveal the answer. Avoid ambiguous clues, or explicitly list other reasonable answers in acceptedAnswers. Do not invent synonyms that fail to fit the clue. Use an empty array if there are no alternatives.\n'+levels+'\nExample structure:\n[{"mode":"vocabulary","level":1,"prompt":"A pet that says meow.","answer":"CAT","acceptedAnswers":[]},{"mode":"vocabulary","level":2,"prompt":"The season after summer.","answer":"AUTUMN","acceptedAnswers":["FALL"]}]\n\nGenerate the requested list now.';
}
root.InkPersonal={cleanWord,validCustom,normalizeQuestion,parseWordList,parseJSONList,parsePracticeList,skillForList,chatbotPrompt};if(typeof module!=='undefined')module.exports=root.InkPersonal;
})(typeof window!=='undefined'?window:globalThis);
